import{_ as t,a0 as o,w as d,s as r,I as n,x as a,a1 as p,A as e,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"自动共享和上传文件到兼容的托管站点 | LCTT x X-CMD","titleTemplate":false,"description":"自动共享和上传文件到兼容的托管站点 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"自动共享和上传文件到兼容的托管站点 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"自动共享和上传文件到兼容的托管站点 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20171027 Share And Upload Files To Compatible Hosting Sites Automatically","title":"自动共享和上传文件到兼容的托管站点","tag":"201912","desc":""},"relativePath":"201912/20171027 Share And Upload Files To Compatible Hosting Sites Automatically.md","filePath":"[post].md"}'),c={name:"201912/20171027 Share And Upload Files To Compatible Hosting Sites Automatically.md"};function g(h,s,u,f,m,b){const i=o("Link");return d(),r("div",null,[s[23]||(s[23]=n("h1",{id:"自动共享和上传文件到兼容的托管站点",tabindex:"-1"},[a("自动共享和上传文件到兼容的托管站点 "),n("a",{class:"header-anchor",href:"#自动共享和上传文件到兼容的托管站点","aria-label":"Permalink to “自动共享和上传文件到兼容的托管站点”"},"​")],-1)),s[24]||(s[24]=n("p",null,[n("img",{src:"https://www.ostechnix.com/wp-content/uploads/2017/10/Upload-720x340.png",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("前阵子我们写了一个关于 ",-1)),p(i,{href:"https://www.ostechnix.com/easy-fast-way-share-files-internet-command-line/"},{default:e(()=>[...s[0]||(s[0]=[a("Transfer.sh",-1)])]),_:1}),s[2]||(s[2]=a("的指南，它允许你使用命令行通过互联网来分享文件。今天，我们来看看另一种文件分享实用工具 Anypaste。这是一个基于文件类型自动共享和上传文件到兼容托管站点的简单脚本。你不需要去手动登录到托管站点来上传或分享你的文件。Anypaste 将会根据你想上传的文件的类型来",-1)),s[3]||(s[3]=n("strong",null,"自动挑选合适的托管站点",-1)),s[4]||(s[4]=a("。简单地说，照片将被上传到图像托管站点，视频被传到视频站点，代码被传到 pastebin。难道不是很酷的吗？Anypaste 是一个完全开源、免费、轻量的脚本，你可以通过命令行完成所有操作。因此，你不需要依靠那些臃肿的、需要消耗大量内存的 GUI 应用来上传和共享文件。",-1))]),s[25]||(s[25]=l(`<h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>正如我所说，这仅仅是一个脚本。所以不存在任何复杂的安装步骤。只需要将脚本下载后放置在你想要运行的位置（例如 <code>/usr/bin/</code>），并将其设置为可执行文件后就可以直接使用了。此外，你也可以通过下面的这两条命令来快速安装 Anypaste。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo curl -o /usr/bin/anypaste https://anypaste.xyz/sh</span></span>
<span class="line"><span>sudo chmod +x /usr/bin/anypaste</span></span></code></pre></div><p>就是这样简单。如果需要更新老的 Anypaste 版本，只需要用新的可执行文件覆写旧的即可。</p><p>现在，让我们看看一些实例。</p><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h3><p>Anypaste 开箱即用，并不需要特别的配置。默认的配置文件是 <code>~/.config/anypaste.conf</code>，这个文件在你第一次运行 Anypaste 时会自动创建。</p><p>需要配置的选项只有 <code>ap_plugins</code>。Anypaste 使用插件系统上传文件。每个站点（的上传）都由一个特定的插件表示。你可以在 <code>anypaste.conf</code> 文件中的 <code>ap-plugins directive</code> 位置浏览可用的插件列表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># List of plugins</span></span>
<span class="line"><span># If there are multiple compatible plugins, precedence is determined</span></span>
<span class="line"><span># by which one is listed first in this array</span></span>
<span class="line"><span>ap_plugins=(</span></span>
<span class="line"><span># Videos/Gifs</span></span>
<span class="line"><span>&#39;sendvid&#39; &#39;streamable&#39; &#39;gfycat&#39;</span></span>
<span class="line"><span># Images</span></span>
<span class="line"><span>&#39;tinyimg&#39; &#39;vgyme&#39;</span></span>
<span class="line"><span># Audio</span></span>
<span class="line"><span>&#39;instaudio&#39;</span></span>
<span class="line"><span># Text</span></span>
<span class="line"><span>&#39;hastebin&#39; &#39;ixio&#39; &#39;sprunge&#39;</span></span>
<span class="line"><span># Documents</span></span>
<span class="line"><span>&#39;docdroid&#39;</span></span>
<span class="line"><span># Any file</span></span>
<span class="line"><span>&#39;jirafeau&#39; &#39;fileio&#39;</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>如果你要安装一个新的插件，将它添加进这个列表中就可以了。如果你想禁用一个默认插件，只需要将它从列表中移除即可。如果有多个兼容的插件，排列中的第一个会被选择，因此<strong>顺序很重要</strong>。</p><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><p>上传一个简单的文件，例如 <code>test.png</code>，可以运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>anypaste test.png</span></span></code></pre></div><p>输出示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Current file: test.png</span></span>
<span class="line"><span>Attempting to upload with plugin &#39;tinyimg&#39;</span></span>
<span class="line"><span>######################################################################## 100.0%</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Direct Link: https://tinyimg.io/i/Sa1zsjj.png</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Upload complete.</span></span>
<span class="line"><span>All files processed. Have a nice day!</span></span></code></pre></div>`,15)),n("p",null,[s[6]||(s[6]=a("正如输出结果中所看到的，Anypaste 通过自动匹配图像文件 ",-1)),s[7]||(s[7]=n("code",null,"test.png",-1)),s[8]||(s[8]=a(" 发现了兼容的托管站点（",-1)),p(i,{href:"https://tinyimg.io"},{default:e(()=>[...s[5]||(s[5]=[a("https://tinyimg.io",-1)])]),_:1}),s[9]||(s[9]=a("），并将文件上传到了该站点。此外，Anypaste 也为我们提供了用于直接浏览/下载该文件的链接。",-1))]),s[26]||(s[26]=l(`<p>不仅是 png 格式文件，你还可以上传任何其他图片格式的文件。例如，下面的命令将会上传 gif 格式文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ anypaste file.gif</span></span>
<span class="line"><span>Current file: file.gif</span></span>
<span class="line"><span>Plugin &#39;streamable&#39; is compatible, but missing config parameters: &#39;streamable_email&#39; &#39;streamable_password&#39;</span></span>
<span class="line"><span>You can set them in /home/sk/.config/anypaste.conf</span></span>
<span class="line"><span>Attempting to upload with plugin &#39;gfycat&#39;</span></span>
<span class="line"><span>######################################################################## 100.0%</span></span>
<span class="line"><span>Reminder: Gfycat needs time to encode. Your video will not appear right away.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Link: https://gfycat.com/MisguidedQuaintBergerpicard</span></span>
<span class="line"><span>Direct(ish) Link: https://thumbs.gfycat.com/MisguidedQuaintBergerpicard-size_restricted.gif</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Upload complete.</span></span>
<span class="line"><span>All files processed. Have a nice day!</span></span></code></pre></div><p>你可以将链接分享给你的家庭、朋友和同事们。下图是我刚刚将图片上传到 gfycat 网站的截图。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/gfycat.png" alt=""></p><p>也可以一次同时上传多个（相同格式或不同格式）文件。</p><p>下面的例子提供参考，这里我会上传两个不同的文件，包含一个图片文件和一个视频文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>anypaste image.png video.mp4</span></span></code></pre></div><p>输出示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Current file: image.png</span></span>
<span class="line"><span>Attempting to upload with plugin &#39;tinyimg&#39;</span></span>
<span class="line"><span>######################################################################## 100.0%</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Direct Link: https://tinyimg.io/i/au1PHpg.png</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Upload complete.</span></span>
<span class="line"><span>Current file: video.mp4</span></span>
<span class="line"><span>Plugin &#39;streamable&#39; is compatible, but missing config parameters: &#39;streamable_email&#39; &#39;streamable_password&#39;</span></span>
<span class="line"><span>You can set them in /home/sk/.config/anypaste.conf</span></span>
<span class="line"><span>Attempting to upload with plugin &#39;sendvid&#39;</span></span>
<span class="line"><span>######################################################################## 100.0%</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Link: http://sendvid.com/wwy7w96h</span></span>
<span class="line"><span>Delete/Edit: http://sendvid.com/wwy7w96h?secret=39c0af2d-d8bf-4d3d-bad3-ad37432a40a5</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Upload complete.</span></span>
<span class="line"><span>All files processed. Have a nice day!</span></span></code></pre></div><p>Anypaste 针对两个文件自动发现了与之相兼容的托管站点并成功上传。</p><p>正如你在上述用法介绍部分的例子中注意到的，Anypaste 会自动挑选最佳的插件。此外，你可以指定插件进行文件上传，这里提供一个上传到 gfycat 的案例，运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>anypaste -p gfycat file.gif</span></span></code></pre></div><p>输出示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Current file: file.gif</span></span>
<span class="line"><span>Plugin &#39;streamable&#39; is compatible, but missing config parameters: &#39;streamable_email&#39; &#39;streamable_password&#39;</span></span>
<span class="line"><span>You can set them in /home/sk/.config/anypaste.conf</span></span>
<span class="line"><span>Attempting to upload with plugin &#39;gfycat&#39;</span></span>
<span class="line"><span>######################################################################## 100.0%</span></span>
<span class="line"><span>Reminder: Gfycat needs time to encode. Your video will not appear right away.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Link: https://gfycat.com/GrayDifferentCollie</span></span>
<span class="line"><span>Direct(ish) Link: https://thumbs.gfycat.com/GrayDifferentCollie-size_restricted.gif</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Upload complete.</span></span>
<span class="line"><span>All files processed. Have a nice day!</span></span></code></pre></div><p>如果要使用特定插件进行文件上传，可以通过以下命令绕过兼容性检查：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>anypaste -fp gfycat file.gif</span></span></code></pre></div><p>如果你发现在配置文件中忽略了特定的插件，你仍然可以强制 Anypaste 去使用特定的插件，只不过需要加上 <code>-xp</code> 参数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>anypaste -xp gfycat file.gif</span></span></code></pre></div><p>如果想要以交互模式上传文件，可以在命令后加上 <code>-i</code> 标签：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ anypaste -i file.gif</span></span>
<span class="line"><span>Current file: file.gif</span></span>
<span class="line"><span>Determine compatible plugins automatically? [Y/n] **n**</span></span>
<span class="line"><span>The following plugins were found: &#39;sendvid&#39; &#39;streamable&#39; &#39;gfycat&#39; &#39;tinyimg&#39; &#39;vgyme&#39; &#39;instaudio&#39; &#39;hastebin&#39; &#39;ixio&#39; &#39;sprunge&#39; &#39;docdroid&#39; &#39;jirafeau&#39; &#39;fileio&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Enter the (partial) name of a plugin, or nothing for automatic selection</span></span>
<span class="line"><span>**gfycat**</span></span>
<span class="line"><span>Attempt to upload with plugin &#39;gfycat&#39;? [Y/n] **y**</span></span>
<span class="line"><span>Attempting to upload with plugin &#39;gfycat&#39;</span></span>
<span class="line"><span>######################################################################## 100.0%</span></span>
<span class="line"><span>Reminder: Gfycat needs time to encode. Your video will not appear right away.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Link: https://gfycat.com/WaryAshamedBlackbear</span></span>
<span class="line"><span>Direct(ish) Link: https://thumbs.gfycat.com/WaryAshamedBlackbear-size_restricted.gif</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Upload complete.</span></span>
<span class="line"><span>All files processed. Have a nice day!</span></span></code></pre></div><p>正如你所见，Anypaste 首先询问了我是否需要自动确定插件。因为我不想自动寻找插件，所以我回复了 “No”。之后，Anypaste 列出了所有可选择的插件，并要求我从列表中选择一个。同样的，你可以上传和共享不同类型的文件，相关文件会被上传到相兼容的站点。</p><p>无论你何时上传一个视频文件，Anypaste 都会将其上传到以下站点中的一个：</p><ol><li>sendvid</li><li>streamable</li><li>gfycat</li></ol><p>这里注意列表顺序，Anypaste 将首先将文件上传到 sendvid 站点，如果没有 sendvid 的插件可供使用，Anypaste 将会尝试顺序中的另外两个站点。当然你也可以通过更改配置文件来修改顺序。</p><p>图像文件上传站点：</p><ol><li>tinyimg.io</li><li>vgy.me</li></ol><p>音频文件上传站点：</p><ol><li>instaud</li></ol><p>文本文件上传站点：</p><ol><li>hastebin</li><li>ix.io</li><li>sprunge.us</li></ol><p>文档上传站点：</p><ol><li>docdroid</li></ol><p>其他任意类型的文件上传站点：</p><ol><li>jirafeau</li><li>file.io</li></ol><p>上面列出来的部分站点一段特定的时间后会删除上传的内容，所以在上传和分享内容时应先明确这些站点的条款和条件。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>在我看来，识别文件并决定将其上传到何处的想法非常棒，而且开发者也以恰当的方式完美地实现了它。毫无疑问，Anypaste 对那些在互联网上需要频繁分享文件的人们非常有用，我希望你也能这么觉得。</p><p>这就是今天的全部内容，后面会有越来越多的好东西分享给大家。再见啦！</p><hr>`,39)),n("p",null,[s[11]||(s[11]=a("via: ",-1)),p(i,{href:"https://www.ostechnix.com/anypaste-share-upload-files-compatible-hosting-sites-automatically/"},{default:e(()=>[...s[10]||(s[10]=[a("https://www.ostechnix.com/anypaste-share-upload-files-compatible-hosting-sites-automatically/",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=a("作者：",-1)),p(i,{href:"https://www.ostechnix.com/author/sk/"},{default:e(()=>[...s[12]||(s[12]=[a("SK",-1)])]),_:1}),s[16]||(s[16]=a(" 译者：",-1)),p(i,{href:"https://github.com/lixin555"},{default:e(()=>[...s[13]||(s[13]=[a("lixin555",-1)])]),_:1}),s[17]||(s[17]=a(" 校对：",-1)),p(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[20]||(s[20]=a("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[18]||(s[18]=[a("LCTT",-1)])]),_:1}),s[21]||(s[21]=a(" 原创编译，",-1)),p(i,{href:"https://linux.cn/"},{default:e(()=>[...s[19]||(s[19]=[a("Linux中国",-1)])]),_:1}),s[22]||(s[22]=a(" 荣誉推出",-1))])])}const v=t(c,[["render",g]]);export{C as __pageData,v as default};
